commit ded29349cf2c1f084473e22a963af8af149c6063
Author: hkjang <gagagiga@naver.com>
Date:   Tue Sep 29 07:06:50 2026 +0900

    fix(mcp): close truncated code blocks with their opening fence length

package mcp

import (
	"fmt"
	"strconv"
	"strings"
)

// Response budgeting. An answer is cut at a section or line boundary so a
// truncated reply still reads as the document it was.

const (
	// DefaultResponseBytes bounds one tool answer when the operator set no
	// per-tool budget. Roughly six thousand tokens: large enough for a full
	// search page, small enough to leave the agent room to work.
	DefaultResponseBytes = 24 << 10
	// MinResponseBytes keeps a budget from becoming a header with no content.
	MinResponseBytes = 2000
	// MaxResponseBytes is the ceiling an operator or caller may raise a tool to.
	MaxResponseBytes = 256 << 10
)

// clampResponse trims one answer to the byte budget without hiding that it did
// so. Two properties matter for an agent reading the result:
//
//   - the cut lands on a result boundary, so the last entry is whole rather than
//     ending mid-line, and
//   - the trailing Notes section survives, because that is where the tool
//     explains which retrieval path ran and what the ACL filtered. Losing it
//     would turn "indexing, answered live" into an unexplained short answer.
func clampResponse(text string, budget int) string {
	if budget <= 0 || len(text) <= budget {
		return text
	}
	body, notes := text, ""
	if at := strings.LastIndex(text, "\n### Notes\n"); at >= 0 {
		body, notes = text[:at], text[at:]
	}
	// The notes only keep their reservation while they stay a small part of the
	// budget; an oversized tail would leave no room for actual results.
	reserved := len(notes)
	if reserved > budget/3 {
		body, notes, reserved = text, "", 0
	}
	total := sectionCount(body)
	room := budget - reserved - responseNoticeBytes
	if room < MinResponseBytes/2 {
		room = budget / 2
	}
	kept := cutAtBoundary(body, room)
	shown := sectionCount(kept)
	notice := fmt.Sprintf("\n\n### Truncated\n- This answer was cut to the %s byte budget of this tool; %s bytes were produced.\n",
		thousands(budget), thousands(len(text)))
	if total > 0 {
		notice += fmt.Sprintf("- %d of %d result sections are included. The rest are not lost, only unsent.\n", shown, total)
	}
	notice += "- Narrow the next call instead of retrying the same one: add libraryId or path, lower limit, or read a line range with read-file.\n"
	return closeOpenFence(strings.TrimRight(kept, "\n")) + notice + notes
}

func boolInt(value bool) int {
	if value {
		return 1
	}
	return 0
}

// responseNoticeBytes reserves room for the truncation notice itself, so adding
// it can never push the answer back over the budget.
const responseNoticeBytes = 320

// sectionCount counts the result entries of a formatted answer. The formatters
// use a `### ` heading per result, and the list formatters use a `- ` item.
func sectionCount(text string) int {
	if count := strings.Count(text, "\n### "); count > 0 {
		return count
	}
	return strings.Count(text, "\n- ")
}

// cutAtBoundary keeps as much of the answer as the room allows, ending it
// somewhere a reader can see the seam.
//
// Every candidate boundary has to keep most of the room, which the paragraph
// and line rules used to skip. A file with no blank line after its first few —
// a minified bundle, a CSV, densely packed code — has its last "\n\n" right
// before the content starts, and cutting there returned a header and nothing
// else: read-file asked for twelve thousand bytes and answered with six
// hundred, while the notice said the answer had been cut to the budget.
func cutAtBoundary(text string, limit int) string {
	if limit >= len(text) {
		return text
	}
	window := text[:limit]
	enough := func(at int) bool { return at > 0 && at*10 >= limit*6 }
	if at := strings.LastIndex(window, "\n### "); enough(at) {
		return text[:at]
	}
	if at := strings.LastIndex(window, "\n\n"); enough(at) {
		return text[:at]
	}
	if at := strings.LastIndexByte(window, '\n'); enough(at) {
		return text[:at]
	}
	return runeSafeCut(text, limit)
}

// closeOpenFence terminates a code fence the cut landed inside. Without it the
// notice explaining the truncation, and the notes after it, are read as part of
// the file that was being shown.
func closeOpenFence(text string) string {
	fence := 0
	for _, line := range strings.Split(text, "\n") {
		// The formatters emit backtick fences. Up to three leading spaces
		// are allowed; inline backticks and shorter nested fences are content.
		trimmed := strings.TrimLeft(line, " ")
		if len(line)-len(trimmed) > 3 {
			continue
		}
		run := 0
		for run < len(trimmed) && trimmed[run] == '`' {
			run++
		}
		if fence == 0 {
			if run >= 3 && !strings.Contains(trimmed[run:], "`") {
				fence = run
			}
		} else if run >= fence && strings.Trim(trimmed[run:], " \t\r") == "" {
			fence = 0
		}
	}
	if fence > 0 {
		return text + "\n" + strings.Repeat("`", fence)
	}
	return text
}

// thousands formats a byte count the way the notice reads best.
func thousands(value int) string {
	digits := strconv.Itoa(value)
	var b strings.Builder
	for index, char := range digits {
		if index > 0 && (len(digits)-index)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteRune(char)
	}
	return b.String()
}
package mcp

import (
	"fmt"
	"strings"
	"testing"
)

// A file that shows a fenced block of its own must not end the block the answer
// opened around it.
//
// read-file escalated to four backticks when the content held three, and
// get-symbol-context did not escalate at all, so a Python module whose docstring
// documents its usage came back with the fence closed in the middle of the
// docstring: the function body, the citation and the notes after it read as
// prose, and the last fence opened a block that never closes.
func TestFencedContentStaysInsideOneBlock(t *testing.T) {
	s := fixture(t)
	must := func(query string, args ...any) {
		t.Helper()
		if _, err := s.store.DB.Exec(query, args...); err != nil {
			t.Fatal(err)
		}
	}
	// A module docstring that shows how the module is used. The example fence sits
	// at column zero, which is where a docstring puts it.
	module := strings.Join([]string{
		`"""GPU probe helpers.`,
		``,
		`Example:`,
		``,
		"```python",
		`from gpu import probe`,
		"```",
		`"""`,
		``,
		`def probe():`,
		`    return None`,
	}, "\n")
	// A README that documents how to write a fenced block has to wrap that block
	// in a longer fence, which the fixed escalation to four backticks cannot hold.
	readme := strings.Join([]string{
		`# Fences`,
		``,
		`Show a Python block like this:`,
		``,
		"````markdown",
		"```python",
		`probe()`,
		"```",
		"````",
	}, "\n")
	must(`INSERT INTO code_symbols(id,repository_id,ref_name,commit_id,file_path,name,qualified_name,symbol_kind,language,signature,documentation,line_start,line_end,content_hash)
		VALUES('s9','r1','main','4fa21bd','gpu/probe.py','probe','probe','function','python','def probe():','Probes the GPU.',10,11,'sh9')`)
	must(`INSERT INTO document_chunks(id,repository_id,ref_name,commit_id,file_path,line_start,line_end,heading,content_type,content,content_hash)
		VALUES('c9','r1','main','4fa21bd','gpu/probe.py',1,11,'probe','code',?,'h9')`, module)
	must(`INSERT INTO document_chunks(id,repository_id,ref_name,commit_id,file_path,line_start,line_end,heading,content_type,content,content_hash)
		VALUES('c10','r1','main','4fa21bd','docs/fences.md',1,9,'Fences','document',?,'h10')`, readme)
	must(`INSERT INTO repository_files(repository_id,ref_name,path,base_name,size_bytes,content_indexed,commit_id)
		VALUES('r1','main','docs/fences.md','fences.md',?,1,'4fa21bd')`, len(readme))

	for _, tc := range []struct {
		name, request, wantLine string
	}{
		{
			name:     "get-symbol-context",
			request:  `{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"get-symbol-context","arguments":{"libraryId":"/kcb/clustara","ref":"main","symbol":"probe"}}}`,
			wantLine: "def probe():",
		},
		{
			name:     "read-file",
			request:  `{"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"read-file","arguments":{"libraryId":"/kcb/clustara","ref":"main","path":"docs/fences.md"}}}`,
			wantLine: "probe()",
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			out := call(t, s, tc.request)
			result, ok := out["result"].(map[string]any)
			if !ok {
				t.Fatalf("call failed: %#v", out)
			}
			text := result["content"].([]any)[0].(map[string]any)["text"].(string)
			blocks, unterminated := markdownBlocks(text)
			if unterminated {
				t.Errorf("the answer ends inside a code fence that never closes, so everything after it is read as file content:\n%s", text)
			}
			if len(blocks) != 1 {
				t.Errorf("the content was split across %d code blocks, want 1:\n%s", len(blocks), text)
			}
			if len(blocks) == 0 || !strings.Contains(blocks[0], tc.wantLine) {
				t.Errorf("%q is outside the code block the answer opened:\n%s", tc.wantLine, text)
			}
		})
	}
}

// markdownBlocks reads the fenced blocks of an answer the way a client renders
// them: a fence opens on a line of three or more backticks and closes only on a
// later line of at least as many with nothing else on it. The second return
// value reports a block left open at the end of the answer.
func markdownBlocks(text string) ([]string, bool) {
	var blocks []string
	var body []string
	fence := 0
	for _, line := range strings.Split(text, "\n") {
		run := backtickRun(line)
		if fence == 0 {
			if run >= 3 {
				fence = run
			}
			continue
		}
		if run >= fence && strings.TrimRight(line, "`") == "" {
			blocks, body, fence = append(blocks, strings.Join(body, "\n")), nil, 0
			continue
		}
		body = append(body, line)
	}
	if fence == 0 {
		return blocks, false
	}
	return append(blocks, strings.Join(body, "\n")), true
}

func backtickRun(line string) int {
	count := 0
	for count < len(line) && line[count] == '`' {
		count++
	}
	return count
}

