				VALUES('r1','main','fenced.py','fenced.py',?,1,'4fa21bd')`, []any{len(content)}},
			} {
				if _, err := s.store.DB.Exec(statement.query, statement.args...); err != nil {
					t.Fatal(err)
				}
			}
			for _, tool := range []string{"read-file", "get-symbol-context"} {
